static int cmd_yy_init_globals (void)
{
        /* Initialization is the same as for the non-reentrant scanner.
     * This function is called from cmd_yylex_destroy(), so don't allocate here.
     */

    (cmd_yy_buffer_stack) = 0;
    (cmd_yy_buffer_stack_top) = 0;
    (cmd_yy_buffer_stack_max) = 0;
    (cmd_yy_c_buf_p) = (char *) 0;
    (cmd_yy_init) = 0;
    (cmd_yy_start) = 0;

/* Defined in main.c */
#ifdef CMD_YY_STDINIT
    cmd_yyin = stdin;
    cmd_yyout = stdout;
#else
    cmd_yyin = (FILE *) 0;
    cmd_yyout = (FILE *) 0;
#endif

    /* For future reference: Set errno on error, since we are called by
     * cmd_yylex_init()
     */
    return 0;
}

/* cmd_yylex_destroy is for both reentrant and non-reentrant scanners. */
int cmd_yylex_destroy  (void)
{
    
    /* Pop the buffer stack, destroying each element. */
	while(CMD_YY_CURRENT_BUFFER){
		cmd_yy_delete_buffer(CMD_YY_CURRENT_BUFFER  );
		CMD_YY_CURRENT_BUFFER_LVALUE = NULL;
		cmd_yypop_buffer_state();
	}

	/* Destroy the stack itself. */
	cmd_yyfree((cmd_yy_buffer_stack) );
	(cmd_yy_buffer_stack) = NULL;

    /* Reset the globals. This is important in a non-reentrant scanner so the next time
     * cmd_yylex() is called, initialization will occur. */
    cmd_yy_init_globals( );

    return 0;
}

